"""
StyleLock AI - Backend Server v50
- Fixed home screen display
- Added photo library option
- Loading screen shows user selfie
- VMODEL + remove.bg API integration
"""

import os
import base64
import httpx
import asyncio
from fastapi import FastAPI, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse, JSONResponse

ANTHROPIC_API_KEY = os.getenv("ANTHROPIC_API_KEY", "")
VMODEL_API_KEY = os.getenv("VMODEL_API_KEY", "")
RAZORPAY_KEY_ID = os.getenv("RAZORPAY_KEY_ID", "")
RAZORPAY_KEY_SECRET = os.getenv("RAZORPAY_KEY_SECRET", "")
REMOVEBG_API_KEY = os.getenv("REMOVEBG_API_KEY", "")
ENABLE_BG_REMOVAL = os.getenv("ENABLE_BG_REMOVAL", "false").lower() == "true"

VMODEL_API_URL = "https://developer.vmodel.ai/api/vmodel/hairchange"

# Hairstyle IDs for VMODEL API
HAIRSTYLES = {
    "bold": {"id": "101", "name": "BOLD", "top_length": "3 inches", "sides": "0.5 fade", "texture": "textured", "products": "matte clay"},
    "clean": {"id": "102", "name": "CLEAN", "top_length": "2 inches", "sides": "skin fade", "texture": "smooth", "products": "pomade"},
    "trending": {"id": "103", "name": "TRENDING", "top_length": "4 inches", "sides": "1 guard", "texture": "wavy", "products": "sea salt spray"}
}

app = FastAPI(title="StyleLock AI v50")

app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

@app.get("/")
async def root():
    return {
        "app": "StyleLock AI",
        "version": "50",
        "status": "running",
        "apis": {
            "anthropic": "configured" if ANTHROPIC_API_KEY else "not configured",
            "vmodel": "configured" if VMODEL_API_KEY else "not configured",
            "razorpay": "configured" if RAZORPAY_KEY_ID else "demo mode",
            "removebg": "configured" if REMOVEBG_API_KEY else "not configured",
            "bg_removal_enabled": ENABLE_BG_REMOVAL
        }
    }

@app.post("/api/create-order")
async def create_razorpay_order():
    if not RAZORPAY_KEY_ID:
        return {"order_id": "demo", "amount": 4900, "currency": "INR", "demo": True}
    import razorpay
    client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
    order = client.order.create({"amount": 4900, "currency": "INR", "payment_capture": 1})
    return {"order_id": order["id"], "amount": 4900, "currency": "INR"}

async def remove_background(image_base64: str) -> str:
    """Remove background using remove.bg API"""
    if not REMOVEBG_API_KEY or not ENABLE_BG_REMOVAL:
        return image_base64
    
    try:
        # Extract base64 data (remove data:image/...;base64, prefix if present)
        if "base64," in image_base64:
            image_data = image_base64.split("base64,")[1]
        else:
            image_data = image_base64
        
        async with httpx.AsyncClient(timeout=30.0) as client:
            response = await client.post(
                "https://api.remove.bg/v1.0/removebg",
                data={"size": "auto", "image_file_b64": image_data},
                headers={"X-Api-Key": REMOVEBG_API_KEY}
            )
            
            if response.status_code == 200:
                return "data:image/png;base64," + base64.b64encode(response.content).decode()
            else:
                print(f"remove.bg error: {response.status_code}")
                return image_base64
    except Exception as e:
        print(f"remove.bg exception: {e}")
        return image_base64

async def generate_hairstyle_vmodel(image_base64: str, hairstyle_id: str) -> str:
    """Generate hairstyle using VMODEL API"""
    if not VMODEL_API_KEY:
        return None
    
    try:
        # Extract base64 data
        if "base64," in image_base64:
            image_data = image_base64.split("base64,")[1]
        else:
            image_data = image_base64
        
        async with httpx.AsyncClient(timeout=60.0) as client:
            response = await client.post(
                VMODEL_API_URL,
                json={
                    "image": image_data,
                    "hairstyle_id": hairstyle_id
                },
                headers={
                    "Authorization": f"Bearer {VMODEL_API_KEY}",
                    "Content-Type": "application/json"
                }
            )
            
            if response.status_code == 200:
                data = response.json()
                if data.get("result"):
                    return data["result"]
            
            print(f"VMODEL error: {response.status_code} - {response.text[:200]}")
            return None
    except Exception as e:
        print(f"VMODEL exception: {e}")
        return None

@app.post("/api/generate-looks")
async def generate_looks(request: Request):
    """Generate 3 hairstyle looks using VMODEL API"""
    try:
        data = await request.json()
        image_base64 = data.get("image", "")
        
        if not image_base64:
            return JSONResponse({"error": "No image provided"}, status_code=400)
        
        # Remove background if enabled
        processed_image = await remove_background(image_base64)
        
        # Generate looks in parallel
        looks = []
        
        if VMODEL_API_KEY:
            # Try to generate with VMODEL
            tasks = []
            for style_key, style_info in HAIRSTYLES.items():
                tasks.append(generate_hairstyle_vmodel(processed_image, style_info["id"]))
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            for (style_key, style_info), result in zip(HAIRSTYLES.items(), results):
                if result and not isinstance(result, Exception):
                    looks.append({
                        "name": style_info["name"],
                        "image": result,
                        "top_length": style_info["top_length"],
                        "sides": style_info["sides"],
                        "texture": style_info["texture"],
                        "products": style_info["products"]
                    })
                else:
                    # Fallback to static image
                    looks.append({
                        "name": style_info["name"],
                        "image": f"https://stylelock-production.up.railway.app/static/hairstyle_{style_key}.jpg",
                        "top_length": style_info["top_length"],
                        "sides": style_info["sides"],
                        "texture": style_info["texture"],
                        "products": style_info["products"]
                    })
        else:
            # No API key - use static images
            for style_key, style_info in HAIRSTYLES.items():
                looks.append({
                    "name": style_info["name"],
                    "image": f"https://stylelock-production.up.railway.app/static/hairstyle_{style_key}.jpg",
                    "top_length": style_info["top_length"],
                    "sides": style_info["sides"],
                    "texture": style_info["texture"],
                    "products": style_info["products"]
                })
        
        return {"looks": looks}
        
    except Exception as e:
        print(f"generate_looks error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)

